                                  {/* Image */}
                                  <Show
                                    fallback={
                                      <div class="flex h-full w-full items-center justify-center bg-gradient-to-br from-blue-950/30 to-slate-950/40">
                                        <span class="font-bold text-5xl text-white/15">
