                                  {/* Title */}
                                  <div class="absolute right-0 bottom-0 left-0 p-3.5">
                                    <h3 class="line-clamp-2 font-semibold text-sm text-white drop-shadow-lg">
                                      {item.Name}
                                    </h3>
