                                    </Show>
                                  </div>
                                </div>
                              </a>
                            )}
                          </For>
                        </div>
                      </div>
                    </Match>
                  </Switch>
                )}
              </QueryBoundary>

              {/* ── Active Jellyseerr Requests (current user) ── */}
              <ActiveRequestsSection />

              {/* ── Continue Watching ── */}
              <QueryBoundary
                loadingFallback={
                  <LoadingSection
