                              if (mins <= 0) {
                                return null;
                              }
                              if (mins < 60) {
                                return `${mins}m left`;
                              }
                              const h = Math.floor(mins / 60);
                              const m = mins % 60;
                              return m > 0 ? `${h}h ${m}m left` : `${h}h left`;
                            })();

                            const episodeLabel = (() => {
                              if (!isEpisode) {
